p_scheduled_time.value:
@if(
  and(
    not(equals(pipeline().parameters.p_scheduled_time, null)),
    not(equals(trim(pipeline().parameters.p_scheduled_time), ''))
  ),
  pipeline().parameters.p_scheduled_time,
  if(
    not(equals(pipeline().TriggerTime, null)),
    formatDateTime(pipeline().TriggerTime, 'yyyy-MM-dd HH:mm:ss'),
    formatDateTime(convertTimeZone(utcNow(), 'UTC', 'Korea Standard Time'), 'yyyy-MM-dd HH:mm:ss')
  )
)
